def write(name,parts):(REP/name).write_text('\n\n'.join(parts)+'\n')
def ms(v):return f'{np.mean(v):.4f} ± {np.std(v,ddof=1):.4f}' if len(v)>1 else f'{np.mean(v):.4f}'
def macro(rows,key):
 # Each full-system row has five seeds; absent strata are descriptive available-system means.
 return [np.mean([r[key] for r in rows if r['seed']==s]) for s in range(5) if any(r['seed']==s for r in rows)]
